/// Throws on a malformed class/group so [isAllowedByConfig] can skip the
/// pattern the way Java skips a failing `getPathMatcher` evaluation.
String _globToRegexSource(String glob) {
  final out = StringBuffer();
  var i = 0;
  while (i < glob.length) {
    switch (glob[i]) {
      case '*':
