    /** Returns the index of the first glob wildcard character, or {@code -1} if none. */
    private static int indexOfWildcard(String s) {
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '*' || c == '?' || c == '{' || c == '[') {
